import {normalize,fresh,completed,access,canEnter,enter,award,restore,achievements} from './core.mjs';
import {makeQuestion} from './questions.mjs';
import {soundEnabled,setSoundEnabled,playSuccessSound} from './sound.mjs';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),toast=document.querySelector('#toast');
const KEY='so-viet-player-v1';let data,state,region,tab='landmark',query='',view='book',zoom=1,pan=[0,0],selectedStart='',startQuery='',quiz=null,revealTimer=null,toastTimer,storageWarning=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={speaker:'<path d="M11 4 5 9H2v6h3l6 5zM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/>',muted:'<path d="M11 4 5 9H2v6h3l6 5zM16 9l6 6M22 9l-6 6"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z"/><path d="M9 3v15M15 6v15"/>',food:'<path d="M3 11h18c0 6-4 9-9 9s-9-3-9-9ZM6 22h12M14 3l-4 5M20 3l-7 5"/>',trophy:'<path d="M7 3h10v7a5 5 0 0 1-10 0zM12 15v6M8 21h8M7 5H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',check:'<path d="m5 12 5 5L20 6"/>',arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m15 5-7 7 7 7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>',book:'<path d="M12 5C8 2 3 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-2-7-1-10 1Zm0 0v16"/>',plus:'<path d="M5 12h14M12 5v14"/>',minus:'<path d="M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/>'};
function icon(id){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.spark}</svg>`;}
function notify(s){toast.textContent=s;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),4500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!storageWarning){storageWarning=true;notify('Trình duyệt không lưu được tiến độ. Hãy xuất bản sao trong Hồ sơ.');}}}
function byRegion(id){return data.regions.find(r=>r.id===id);}
function chapter(id){return data.chapters.find(c=>c.id===id);}
function card(id){return data.cards.find(c=>c.id===id);}
function earned(c){return state?.earned.includes(c.id)??false;}
function art(c,cls='',reveal=earned(c)){if(reveal&&state?.shiny?.includes(c.id))cls+=' shiny';if(c.landmarkArt)return `<div class="art landmark-atlas ${cls}" style="--fx:${c.landmarkArt.tile%4};--fy:${Math.floor(c.landmarkArt.tile/4)};background-image:url('assets/landmark-atlas-${c.landmarkArt.sheet}.png')" role="img" aria-label="${esc(reveal?'Tranh minh họa '+c.name:'Hình thẻ chưa mở')}"></div>`;if(c.foodArt)return `<div class="art food-atlas ${cls}" style="--food-sheet:${c.foodArt.sheet};--fx:${c.foodArt.tile%4};--fy:${Math.floor(c.foodArt.tile/4)};background-image:url('assets/food-atlas-${c.foodArt.sheet}.png')" role="img" aria-label="${esc(reveal?'Tranh minh họa '+c.name:'Tranh món ăn')}"></div>`;return c.art!=null?`<div class="art atlas ${cls}" style="--ax:${c.art%4};--ay:${Math.floor(c.art/4)}" role="img" aria-label="${esc(reveal?'Tranh minh họa '+c.name:'Hình thẻ chưa mở')}"></div>`:`<div class="art placeholder ${c.type==='food'?'food-art':''} ${cls}" aria-label="Minh họa biểu tượng" role="img">${icon(c.type==='food'?'food':'map')}<span>Minh họa</span></div>`;}
function soundButton(){return `<button class="sound-toggle" data-action="sound" aria-label="${soundEnabled()?'Tắt âm thanh':'Bật âm thanh'}" aria-pressed="${soundEnabled()}" title="${soundEnabled()?'Tắt âm thanh':'Bật âm thanh'}">${icon(soundEnabled()?'speaker':'muted')}</button>`;}
function header(){return `<header class="topbar"><a href="#" class="brand" data-action="home" aria-label="Mật Mã Việt Nam · Trang chủ"><img class="brand-mark" src="assets/brand-mark.svg" alt="" width="32" height="36"><span class="brand-wordmark">Mật Mã Việt Nam<small>Nhật ký khám phá Việt Nam</small></span></a><div class="top-right">${soundButton()}${state?`<button class="profile" data-action="profile"><span>${esc(state.name)}</span><b>${state.earned.length}</b></button>`:'<span class="edition">Bản chơi thử</span>'}</div></header>`;}

function startScreen(){
 const rs=data.regions.filter(r=>normalize(r.name+' '+chapter(r.chapter).name).includes(normalize(startQuery)));
 app.innerHTML=header()+`<main id="main" class="start-layout"><section class="welcome"><span class="eyebrow">MỘT CUỐN SỔ · NGÀN ĐIỀU THÚ VỊ</span><h1>Việt Nam mình,<br><em>đi đâu trước?</em></h1><p>Mỗi vùng đất là một trang chuyện.<br>Giải câu đố, gom thẻ xinh, mở những chân trời mới.</p><div class="mini-badges"><span>34 chapter</span><span>63 vùng khám phá</span><span>${data.cards.length} thẻ</span></div><div class="welcome-art"><div class="postcard one">${art({...data.cards.find(c=>c.art===6)})}<b>Những miền di sản</b></div><div class="postcard two">${art({...data.cards.find(c=>c.art===11)})}<b>Hương vị quê nhà</b></div><span class="art-spark">✦</span></div><p class="local-note">${icon('lock')} Hồ sơ lưu trên trình duyệt của bạn.</p></section><section class="start-panel"><div class="section-kicker">01 / BẮT ĐẦU HÀNH TRÌNH</div><h2>Chọn nơi bạn khởi hành</h2><p>Chọn một trong 63 vùng. Bạn có thể bắt đầu ở bất cứ đâu.</p><label class="field-label" for="player-name">Tên nhà thám hiểm</label><input id="player-name" maxlength="40" placeholder="Bạn muốn được gọi là gì?" autocomplete="nickname"><label class="searchbox">${icon('search')}<input id="start-search" type="search" placeholder="Tìm tỉnh, thành…" value="${esc(startQuery)}" aria-label="Tìm vùng xuất phát"></label><div class="region-picker" role="group" aria-label="63 vùng xuất phát">${rs.map(r=>`<button class="region-choice ${selectedStart===r.id?'selected':''}" data-start="${r.id}" aria-pressed="${selectedStart===r.id}"><span>${esc(r.name)}</span><small>${esc(chapter(r.chapter).name)}</small>${selectedStart===r.id?icon('check'):''}</button>`).join('')||'<p class="empty">Không tìm thấy vùng phù hợp.</p>'}</div><div class="start-bottom"><span id="selected-label">${selectedStart?'Khởi hành từ '+esc(byRegion(selectedStart).name):'Chọn một vùng để tiếp tục'}</span><button id="begin" class="primary" ${selectedStart?'':'disabled'}>Mở sổ hành trình ${icon('arrow')}</button></div></section></main><footer class="footer">Một hành trình nhỏ, một Việt Nam thật gần. <button data-action="about">Về bản chơi thử</button></footer>`;
 document.querySelector('#start-search').oninput=e=>{const name=document.querySelector('#player-name').value;const pos=e.target.selectionStart;startQuery=e.target.value;startScreen();document.querySelector('#player-name').value=name;const input=document.querySelector('#start-search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}};
 document.querySelectorAll('[data-start]').forEach(el=>el.onclick=()=>{const name=document.querySelector('#player-name').value;selectedStart=el.dataset.start;startScreen();document.querySelector('#player-name').value=name;});
 document.querySelector('#begin').onclick=()=>{const input=document.querySelector('#player-name');if(!input.value.trim()){input.focus();notify('Nhập tên nhà thám hiểm để mở sổ nhé.');return;}state=fresh(input.value,selectedStart);region=selectedStart;save();render();notify('Chào '+state.name+'! Chọn một thẻ để bắt đầu khám phá.');};bindGlobal();
}
// Equirectangular projection with a fixed latitude correction for consistent map/pin alignment.
const project=([lon,lat])=>[lon*.94,-lat];
function rings(g){return g.type==='Polygon'?g.coordinates:g.coordinates.flat();}
function path(g){return rings(g).map(r=>'M'+r.map(x=>project(x).map(n=>n.toFixed(4)).join(',')).join('L')+'Z').join('');}
function bounds(features){const ps=features.flatMap(f=>rings(f.geometry).flat().map(project));let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const [x,y]of ps){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);}return [minX,minY,maxX-minX,maxY-minY];}
function mapSvg(global=false,opts={}){
 const ch=opts.chapter||chapter(byRegion(region).chapter),features=global?data.chapters:data.regions.filter(r=>r.chapter===ch.id),bb=bounds(features),pad=Math.max(bb[2],bb[3])*.09;
 const scale=global?zoom:1;const w=(bb[2]+pad*2)/scale,h=(bb[3]+pad*2)/scale;const vb=[bb[0]-pad+(bb[2]+pad*2-w)/2+pan[0],bb[1]-pad+(bb[3]+pad*2-h)/2+pan[1],w,h];
 const a=access(data,state);const stroke=Math.max(w,h)*.004,fs=Math.max(w,h)*.032;
 const shapes=features.map(f=>{let available=global?a.chapters.has(f.id):a.regions.has(f.id),done=global?f.regions.every(id=>completed(data,state,id)):completed(data,state,f.id);const active=global?f.id===ch.id:f.id===region;return `<path class="province ${available?'available':'locked'} ${active?'active':''} ${done?'done':''}" d="${path(f.geometry)}" fill-rule="evenodd" style="stroke-width:${stroke}" data-${global?'chapter':'region'}="${f.id}" tabindex="0" role="button" aria-label="${esc(f.name)}${available?'':' · Chưa mở'}"><title>${esc(f.name)}${done?' · Đã hoàn thành':available?' · Có thể khám phá':' · Chưa mở'}</title></path>`;}).join('');
 const labels=!global?features.map(f=>{const [x,y]=project(f.center);return `<text class="region-label" x="${x}" y="${y}" font-size="${fs}" text-anchor="middle" pointer-events="none">${esc(f.name)}</text>${a.regions.has(f.id)?'':`<text x="${x}" y="${y-fs*1.1}" font-size="${fs*1.1}" text-anchor="middle" fill="#6d7e84" pointer-events="none">▣</text>`}`;}).join(''):'';
 const pins=!global?data.cards.filter(c=>c.type==='landmark'&&c.coordinates&&earned(c)&&features.some(f=>f.id===c.region)).map(c=>{const [x,y]=project(c.coordinates);return `<g class="map-pin" data-card="${c.id}" tabindex="0" role="button" aria-label="${esc(c.name)}"><title>${esc(c.name)}</title><circle cx="${x}" cy="${y}" r="${fs*.47}" fill="#f7f0dc" stroke="#087a84" stroke-width="${stroke}"/><circle cx="${x}" cy="${y}" r="${fs*.22}" fill="#ff9971"/></g>`;}).join(''):'';
 return `<svg class="geographic-map ${global?'national':''}" viewBox="${vb.join(' ')}" role="group" aria-label="${global?'Bản đồ 34 tỉnh thành':'Bản đồ chapter '+esc(ch.name)}">${shapes}${labels}${pins}</svg>`;
}
function stats(){return `${state.earned.length} thẻ · ${data.regions.filter(r=>completed(data,state,r.id)).length}/63 vùng`;}
function render(){if(!state){startScreen();return;}if(view==='world'){worldScreen();return;}bookScreen();}
function cardRow(c){const unlocked=earned(c);return `<button class="card-row ${unlocked?'unlocked':'sealed'}" data-card="${c.id}" aria-label="${unlocked?esc(c.name):'Thẻ chưa mở · Bắt đầu thử thách'}"><div class="thumb">${art(c,unlocked?'':'blurred')}${unlocked?'':`<span class="lock-overlay">${icon('lock')}</span>`}</div><span class="card-copy"><span class="card-title">${unlocked?esc(c.name):'Thẻ bí ẩn'}</span></span></button>`;}
function shortStory(c){const text=c.history||c.intro;const sentences=text.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[text];let result='';for(const sentence of sentences){if((result+sentence).length>220)break;result+=sentence;}return result.trim()||c.intro;}
function achievementList(){return `<div class="collection-hint">Dấu ấn của bạn trên khắp Việt Nam</div>${achievements(data,state).map(a=>`<article class="achievement ${a.current>=a.total?'achieved':''}"><div class="medal">${icon(a.icon)}</div><div><h3>${esc(a.name)}</h3><p>${esc(a.intro)}</p><progress max="${a.total}" value="${a.current}" aria-label="${esc(a.name)}"></progress><small>${a.current}/${a.total}${a.current>=a.total?' · Đã đạt':''}</small></div></article>`).join('')}<div class="heritage-section"><h3>Di sản sống</h3><p>Khám phá những thực hành văn hóa được UNESCO ghi danh.</p>${data.heritages.map(h=>`<button class="heritage-link" data-heritage="${h.id}">${icon('spark')}<span>${esc(h.name)}</span>${icon('arrow')}</button>`).join('')}</div>`;}
function bookScreen(){
 const r=byRegion(region),ch=chapter(r.chapter),a=access(data,state);const type=tab==='food'?'food':'landmark';const cs=r.cards.map(card).filter(c=>c.type===type);let content;
 if(tab==='trophy')content=achievementList();else if(tab==='search'){const matches=query.trim()?data.cards.filter(c=>normalize(c.name+' '+byRegion(c.region).name).includes(normalize(query))).slice(0,60):[];content=`<label class="searchbox collection-search">${icon('search')}<input id="collection-search" type="search" value="${esc(query)}" placeholder="Tên địa điểm hoặc món ăn…" aria-label="Tìm địa điểm hoặc món ăn"></label><p class="collection-hint">Tìm trên cả 63 vùng · Không phân biệt dấu tiếng Việt</p><div id="search-results">${query.trim()?matches.map(c=>{const allowed=a.regions.has(c.region);return `<button class="search-result" data-result="${c.id}">${icon(c.type==='food'?'food':'map')}<span><b>${esc(c.name)}</b><small>${esc(byRegion(c.region).name)} · ${allowed?'Có thể khám phá':'Vùng chưa mở'}</small></span>${icon(allowed?'arrow':'lock')}</button>`;}).join('')||'<p class="empty">Chưa tìm thấy. Thử tên khác nhé.</p>':'<div class="empty search-empty">'+icon('search')+'<h3>Bạn đang tìm điều gì?</h3><p>Thử “bánh mì”, “chùa Keo” hoặc “Hà Nội”.</p></div>'}</div>`;}else content=cs.map(cardRow).join('');
 app.innerHTML=header()+`<main id="main" class="game-shell"><div class="journey-top"><span>${icon('pin')} Hành trình của ${esc(state.name)}</span><button class="text-button" data-action="guide">Cách chơi ${icon('book')}</button></div><section class="book"><div class="book-spine"></div><section class="page map-page"><div class="page-corners"></div><div class="page-top"><button class="all-button" data-action="world">${icon('map')} Tất cả</button><span class="chapter-tag">CHAPTER ${String(data.chapters.indexOf(ch)+1).padStart(2,'0')} / 34</span></div><h1>${esc(ch.name)}</h1><div class="title-rule"><span></span>${icon('spark')}<span></span></div><div class="chapter-map">${mapSvg()}</div><div class="map-footer"><span>${icon('book')} ${esc(r.name)}</span><b>${r.cards.filter(id=>state.earned.includes(id)).length}/${r.cards.length} thẻ</b></div><span class="page-number">${String(data.chapters.indexOf(ch)*2+1).padStart(2,'0')}</span></section><section class="page collection-page"><nav class="bookmark-tabs" aria-label="Bộ sưu tập"><button data-tab="landmark" class="bookmark map-tab ${tab==='landmark'?'selected':''}" aria-label="Địa danh" aria-pressed="${tab==='landmark'}" title="Địa danh">${icon('map')}</button><button data-tab="food" class="bookmark food-tab ${tab==='food'?'selected':''}" aria-label="Món ăn" aria-pressed="${tab==='food'}" title="Món ăn">${icon('food')}</button><button data-tab="trophy" class="bookmark trophy-tab ${tab==='trophy'?'selected':''}" aria-label="Thành tựu" aria-pressed="${tab==='trophy'}" title="Thành tựu">${icon('trophy')}</button><button data-tab="search" class="bookmark search-tab ${tab==='search'?'selected':''}" aria-label="Tìm kiếm" aria-pressed="${tab==='search'}" title="Tìm địa điểm hoặc món ăn">${icon('search')}</button></nav><h2>${tab==='landmark'?'Địa Danh Nổi Tiếng':tab==='food'?'Đặc Sản':tab==='trophy'?'Thành Tựu':'Tìm Kiếm'}</h2><div class="collection-scroll">${content}</div><div class="collection-bottom"><span>${tab==='landmark'?icon('map'):tab==='food'?icon('food'):icon('spark')}${tab==='trophy'?'Mỗi chuyến đi, một dấu ấn':tab==='search'?'Tìm kiếm toàn bộ bộ sưu tập':`${cs.filter(earned).length}/${cs.length} ${type==='food'?'đặc sản':'địa danh'} đã khám phá`}</span><span class="page-number">${String(data.chapters.indexOf(ch)*2+2).padStart(2,'0')}</span></div></section></section><div class="below-book"><span>${icon('check')} Tự động lưu trên trình duyệt</span><span>${stats()}</span></div></main><footer class="footer">63 vùng đất. Hành trình của riêng bạn.<button data-action="about">Nguồn & thông tin bản thử</button></footer>`;
 bindGlobal();bindMap();document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();if(tab==='search')document.querySelector('#collection-search').focus();});
 document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>openCard(b.dataset.card));
 document.querySelectorAll('[data-heritage]').forEach(b=>b.onclick=()=>openHeritage(b.dataset.heritage));document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const c=card(b.dataset.result);if(!canEnter(data,state,c.region)){notify('Hoàn thành các vùng trước để mở đường tới '+byRegion(c.region).name+'.');return;}navigate(c.region);openCard(c.id);});
 const search=document.querySelector('#collection-search');if(search)search.oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;bookScreen();const s=document.querySelector('#collection-search');s.focus();try{s.setSelectionRange(pos,pos);}catch{}};
}
function navigate(id){if(!enter(data,state,id)){notify('Vùng này chưa mở. Thu thập đủ 3 thẻ tại vùng đang khám phá nhé.');return;}region=id;state.lastRegion=id;tab='landmark';view='book';pan=[0,0];zoom=1;save();render();}
function worldScreen(){
 const a=access(data,state);app.innerHTML=header()+`<main id="main" class="world-layout"><section class="world-map-panel"><div class="world-heading"><button class="text-button" data-action="book">${icon('back')} Về sổ</button><span>34 CHAPTER · 63 VÙNG KHÁM PHÁ</span></div><h1>Việt Nam, mình đi tiếp nhé!</h1><p>Chọn một chapter để xem các vùng. Kéo bản đồ hoặc dùng nút phóng to.</p><div class="world-map">${mapSvg(true)}<div class="zoom-controls"><button data-zoom="in" aria-label="Phóng to">${icon('plus')}</button><button data-zoom="out" aria-label="Thu nhỏ">${icon('minus')}</button><button data-zoom="reset" aria-label="Đặt lại bản đồ">${icon('map')}</button></div><span class="sea-label">BIỂN ĐÔNG</span></div><p class="map-caption">Bản đồ hành chính được giản lược để hiển thị trong game. Các đảo xa bờ xem ở dữ liệu nguồn.</p></section><aside class="chapter-directory"><h2>Những trang tiếp theo</h2><p>${a.chapters.size}/34 chapter có thể bắt đầu</p><label class="searchbox">${icon('search')}<input id="chapter-search" placeholder="Tìm chapter…" aria-label="Tìm chapter"></label><div class="chapter-list">${data.chapters.map(c=>`<button data-chapter="${c.id}" data-name="${normalize(c.name)}" class="chapter-item ${a.chapters.has(c.id)?'':'locked'}"><span class="chapter-icon">${icon(a.chapters.has(c.id)?'map':'lock')}</span><span><b>${esc(c.name)}</b><small>${c.regions.length} vùng · ${c.regions.filter(id=>completed(data,state,id)).length} hoàn thành</small></span>${icon('arrow')}</button>`).join('')}</div></aside></main>`;bindGlobal();bindMap();document.querySelector('#chapter-search').oninput=e=>document.querySelectorAll('.chapter-item').forEach(b=>b.hidden=!b.dataset.name.includes(normalize(e.target.value)));document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{if(b.dataset.zoom==='reset'){zoom=1;pan=[0,0];}else zoom=Math.max(1,Math.min(8,zoom*(b.dataset.zoom==='in'?1.5:1/1.5)));worldScreen();});
 const svg=document.querySelector('.national');let drag=null,moved=false;
 svg.onpointerdown=e=>{if(e.pointerType==='touch'&&e.isPrimary===false)return;drag={x:e.clientX,y:e.clientY,pan:[...pan],vb:svg.viewBox.baseVal.width};moved=false;};
 svg.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>8)moved=true;if(moved){pan=[drag.pan[0]-dx/svg.clientWidth*drag.vb,drag.pan[1]-dy/svg.clientWidth*drag.vb];const b=svg.viewBox.baseVal;const deltaX=pan[0]-drag.pan[0],deltaY=pan[1]-drag.pan[1];const base=bounds(data.chapters),pad=Math.max(base[2],base[3])*.09;svg.setAttribute('viewBox',[base[0]-pad+(base[2]+2*pad-b.width)/2+pan[0],base[1]-pad+(base[3]+2*pad-b.height)/2+pan[1],b.width,b.height].join(' '));}};
 svg.onpointerup=()=>{drag=null;if(moved){svg.dataset.dragged='true';setTimeout(()=>delete svg.dataset.dragged,100);}};svg.onpointerleave=()=>{drag=null;};
}
function bindMap(){document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{if(document.querySelector('.national')?.dataset.dragged)return;openChapter(b.dataset.chapter);});document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>navigate(b.dataset.region));document.querySelectorAll('.geographic-map [role=button]').forEach(b=>b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});}
function openChapter(id){const c=chapter(id);showDialog(`<h2>${esc(c.name)}</h2><p>Chạm vào vùng trên bản đồ để chọn.</p><div class="chapter-select-map">${mapSvg(false,{chapter:c})}</div>`);document.querySelectorAll('.chapter-select-map [data-region]').forEach(b=>{const select=()=>{if(!canEnter(data,state,b.dataset.region)){notify('Hoàn thành vùng đang chơi để mở đường.');return;}dismissDialog();navigate(b.dataset.region);};b.onclick=select;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};});}
function stopReveal(){clearInterval(revealTimer);revealTimer=null;}
function dismissDialog(){stopReveal();const reward=dialog.dataset.view==='reward';dialog.dataset.view='content';dialog.close();if(reward)render();}
function showDialog(html){stopReveal();dialog.dataset.view='content';dialog.innerHTML=`<button class="dialog-close" aria-label="Đóng">${icon('close')}</button><div class="dialog-content">${html}</div>`;if(!dialog.open)dialog.showModal();dialog.querySelector('.dialog-close').onclick=dismissDialog;}
function openCard(id){const c=card(id);if(!earned(c)){if(!access(data,state).regions.has(c.region)){notify('Vùng này chưa mở.');return;}challengePicker(c);return;}
 showDialog(`<div class="detail-image">${art(c)}</div><span class="eyebrow">${c.type==='food'?'HƯƠNG VỊ QUÊ NHÀ':'DẤU CHÂN KHÁM PHÁ'} · ${esc(byRegion(c.region).name)}</span><h2>${esc(c.name)}</h2>${c.heritage?`<div class="heritage-tag">${icon('spark')} ${esc(c.heritage.kind)} · ${c.heritage.year}</div><p class="heritage-context">Thuộc: ${esc(c.heritage.name)}. Danh hiệu áp dụng cho di sản được ghi danh.</p>`:''}<p class="detail-intro">${esc(shortStory(c))}</p><div class="detail-sources"><a href="${esc(c.source)}" target="_blank" rel="noopener noreferrer">${esc(c.sourceLabel)} ↗</a><span>${c.art!=null||c.landmarkArt||c.foodArt?'Tranh minh họa hoạt hình':'Hình biểu tượng tạm thời'}</span></div>${c.type==='landmark'&&c.coordinates?`<a class="map-source" href="https://www.google.com/maps/search/?api=1&query=${c.coordinates[1]},${c.coordinates[0]}" target="_blank" rel="noopener noreferrer">Xem vị trí trên Google Maps ↗</a>`:''}<button class="primary wide" id="practice">Chơi lại thử thách ${icon('spark')}</button>`);document.querySelector('#practice').onclick=()=>challengePicker(c);
}
function challengePicker(c){startQuiz(c);}
function shuffled(xs){const out=[...xs];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
async function startQuiz(c){
 const item=makeQuestion(data,c,'image');
 quiz={card:c.id,correct:item.correct,done:false,item,attempts:0,startedAt:null};const current=quiz;
 const parts=item.passage.split('{{blank}}');
 const passage=`${esc(parts[0])}<span class="question-blank" aria-label="chỗ trống">…</span>${esc(parts[1]||'')}`;
 showDialog(`<h2>Nhận diện hình ảnh</h2><div class="quiz-image">${art(c,'',false)}<div class="tile-mask" aria-hidden="true">${Array.from({length:16},(_,i)=>`<span data-tile="${i}"></span>`).join('')}</div></div><div class="cloze-passage">${passage}</div>${answerButtons(item.options)}<div id="answer-feedback" role="status" aria-live="polite"></div>`);
 dialog.dataset.view='question';
 const buttons=[...document.querySelectorAll('[data-answer]')];buttons.forEach(b=>{b.disabled=true;b.onclick=()=>answer(b.dataset.answer,b);});
 const image=new Image();const background=getComputedStyle(document.querySelector('.quiz-image .art')).backgroundImage;image.src=background.slice(5,-2);
 try{await image.decode();}catch{if(quiz===current&&dialog.dataset.view==='question')document.querySelector('#answer-feedback').textContent='Chưa tải được tranh. Đóng và mở lại để thử lại.';return;}
 if(quiz!==current||!dialog.open||dialog.dataset.view!=='question')return;
 current.startedAt=performance.now();buttons.forEach(b=>b.disabled=false);
 const order=shuffled([...Array(16).keys()]);let shown=0;
 revealTimer=setInterval(()=>{if(quiz!==current||current.done||!dialog.open){stopReveal();return;}document.querySelector(`[data-tile="${order[shown++]}"]`).classList.add('revealed');if(shown===16)stopReveal();},500);
}
function answerButtons(options){return `<div class="answers">${options.map((o,i)=>`<button data-answer="${esc(o.id)}"><span>${'ABCD'[i]}</span>${esc(o.label)}</button>`).join('')}</div>`;}
function answer(id,button){
 if(!quiz||quiz.done||quiz.startedAt===null||button.getAttribute('aria-disabled')==='true')return;
 if(id!==quiz.correct){
  quiz.attempts++;
  document.querySelectorAll('[data-answer]').forEach(el=>{if(el.dataset.answer===id){el.classList.add('wrong');el.setAttribute('aria-disabled','true');if(el.tagName.toLowerCase()==='button')el.disabled=true;}});
  document.querySelector('#answer-feedback').innerHTML='<p class="incorrect">Chưa đúng. Thử lại nhé.</p>';
  return;
 }
 const elapsed=performance.now()-quiz.startedAt;quiz.done=true;stopReveal();
 const c=card(quiz.card),wasCompleted=completed(data,state,c.region),before=access(data,state),added=award(data,state,c.id);
 if(elapsed<2000){state.shiny??=[];if(!state.shiny.includes(c.id))state.shiny.push(c.id);}
 save();void playSuccessSound();
 const after=access(data,state),newRegions=[...after.regions].filter(x=>!before.regions.has(x)),newChapters=[...after.chapters].filter(x=>!before.chapters.has(x));
 const unlock=!wasCompleted&&completed(data,state,c.region)?`${newRegions.length?'Mở vùng: '+newRegions.map(x=>esc(byRegion(x).name)).join(', '):'Đã hoàn thành vùng '+esc(byRegion(c.region).name)}${newChapters.length?'<br>Mở chapter: '+newChapters.map(x=>esc(chapter(x).name)).join(', '):''}`:'';
 showDialog(`<div class="reward-heading">${icon('spark')}<span>${elapsed<2000?'Thẻ lấp lánh · '+(Math.floor(elapsed/10)/100).toFixed(2)+' giây':added?'Đã nhận thẻ mới':'Trả lời chính xác'}</span></div><article class="reward-card"><div class="reward-art">${art(c,'',true)}</div><div class="reward-card-label"><h2>${esc(c.name)}</h2></div></article><section class="reward-story" aria-label="Giới thiệu"><h3>${c.type==='food'?'Một chút về món ăn':'Lịch sử & giới thiệu'}</h3><p>${esc(shortStory(c))}</p>${c.heritage?`<span class="heritage-tag">${esc(c.heritage.kind)} · ${c.heritage.year}</span>`:''}<a class="reward-source" href="${esc(c.source)}" target="_blank" rel="noopener noreferrer">Đọc thêm tư liệu ↗</a></section>${unlock?`<p class="unlock-message">${unlock}</p>`:''}<button class="primary wide" id="claim">${added?'Cất thẻ vào sổ':'Trở về sổ'} ${icon('book')}</button>`);
 dialog.dataset.view='reward';
 document.querySelector('#claim').onclick=dismissDialog;
 document.querySelector('#claim').focus({preventScroll:true});
 dialog.scrollTop=0;
}

function openHeritage(id){const h=data.heritages.find(x=>x.id===id);showDialog(`<span class="eyebrow">DI SẢN SỐNG · HỒ SƠ CHUNG</span><h2>${esc(h.name)}</h2><p>${esc(h.intro)}</p><p>Không gian liên quan trong bản thử: ${h.regions.map(x=>esc(byRegion(x)?.name||x)).join(', ')}.</p><p class="muted">Di sản phi vật thể là thực hành văn hóa của cộng đồng, không phải một địa điểm duy nhất. Danh sách vùng liên quan còn được bổ sung.</p><a href="${esc(h.source)}" target="_blank" rel="noopener noreferrer">Hồ sơ UNESCO ↗</a>`);}
function profile(){showDialog(`<span class="eyebrow">NHÀ THÁM HIỂM</span><h2>${esc(state.name)}</h2><p>${stats()}</p><p>Hồ sơ được lưu trên trình duyệt này. Xuất bản sao để chuyển sang thiết bị khác.</p><div class="profile-actions"><button id="export" class="primary">${icon('download')} Xuất tiến độ</button><label class="secondary import-label">Nhập tiến độ<input id="import" type="file" accept="application/json,.json" hidden></label><button id="new-game" class="text-button danger">Bắt đầu hành trình mới</button></div>`);
 document.querySelector('#export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mat-ma-viet-nam-tien-do.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};document.querySelector('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1e6){notify('Tệp tiến độ quá lớn.');return;}try{const next=restore(data,await file.text());if(!next)throw Error();state=next;region=state.lastRegion;save();dialog.close();render();notify('Đã khôi phục tiến độ.');}catch{notify('Tệp tiến độ không hợp lệ. Dữ liệu hiện tại vẫn được giữ.');}};
 document.querySelector('#new-game').onclick=()=>{showDialog(`<h2>Bắt đầu lại hành trình?</h2><p>Tiến độ hiện tại trên trình duyệt sẽ bị thay thế. Hãy xuất bản sao trước nếu muốn giữ lại.</p><button class="primary danger" id="confirm-reset">Xóa tiến độ và chọn lại</button>`);document.querySelector('#confirm-reset').onclick=()=>{try{localStorage.removeItem(KEY);}catch{}state=null;selectedStart='';view='book';dialog.close();render();};};}
function about(){showDialog(`<span class="eyebrow">MẬT MÃ VIỆT NAM · BẢN CHƠI THỬ</span><h2>Một Việt Nam thật gần</h2><p>Bản đầu có 34 chapter, 63 vùng và ${data.cards.length} thẻ. Dữ liệu bản đồ được giản lược từ GeoJSON; các vùng trước sắp xếp được tái dựng bằng cách ghép phường/xã theo mã lịch sử.</p><p>Toàn bộ 79 thẻ món ăn và 198 địa danh đã có tranh hoạt hình. Tranh được tạo để minh họa, chưa thay thế ảnh tư liệu đã duyệt.</p><p>Giới thiệu là bản biên tập ngắn; nhiều nguồn Wikipedia đang là liên kết tham khảo, cần duyệt nội dung trước phát hành. Hồ sơ UNESCO dẫn nguồn chính thức. Bộ di sản phi vật thể đang được bổ sung, không coi bản thử là danh mục đầy đủ.</p><p>Hồ sơ lưu cục bộ, chưa có tài khoản máy chủ hoặc đồng bộ tự động.</p><a href="credits.html" target="_blank" rel="noopener">Nguồn dữ liệu và giấy phép ↗</a>`);}
function guide(){showDialog(`<span class="eyebrow">CÁCH CHƠI</span><h2>Mỗi thẻ, một điều mới</h2><ol class="guide-list"><li>Chọn thẻ chưa mở trong Địa danh hoặc Món ăn.</li><li>Quan sát tranh hé ngẫu nhiên 16 ô, mỗi 0,5 giây một ô, rồi điền đoạn văn. Đúng dưới 2 giây nhận thẻ lấp lánh. Sai có thể thử lại.</li><li>Đủ 3 thẻ khác nhau tại một vùng sẽ mở các vùng còn lại trong chapter.</li><li>Hoàn thành mọi vùng trong chapter để mở các chapter tiếp giáp.</li><li>Vào Tất cả để phóng to, kéo bản đồ và chọn nơi đi tiếp.</li></ol><p>Thành tựu tính trên toàn bộ hành trình. Nhấn kính lúp để tìm địa điểm hoặc đặc sản.</p>`);}
function bindGlobal(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>{e.preventDefault();const action=b.dataset.action;if(action==='home'){if(state){view='book';render();}}if(action==='world'){view='world';zoom=1;pan=[0,0];render();}if(action==='book'){view='book';render();}if(action==='sound'){setSoundEnabled(!soundEnabled());b.innerHTML=icon(soundEnabled()?'speaker':'muted');b.setAttribute('aria-label',soundEnabled()?'Tắt âm thanh':'Bật âm thanh');b.setAttribute('title',soundEnabled()?'Tắt âm thanh':'Bật âm thanh');b.setAttribute('aria-pressed',String(soundEnabled()));}if(action==='profile')profile();if(action==='about')about();if(action==='guide')guide();});}
dialog.addEventListener('close',()=>{stopReveal();if(dialog.dataset.view==='reward'){dialog.dataset.view='content';render();}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dismissDialog();}});
try{const response=await fetch('./data.json');if(!response.ok)throw Error('Không tải được dữ liệu');data=await response.json();let raw=null;try{raw=localStorage.getItem(KEY);}catch{}state=raw?restore(data,raw):null;region=state?.lastRegion||data.regions[0].id;render();if(raw&&!state)notify('Bản lưu chưa hợp lệ. Bạn có thể tạo hành trình mới hoặc nhập bản sao.');}catch(error){app.innerHTML=`<main class="load-error"><h1>Chưa mở được sổ</h1><p>Kiểm tra kết nối rồi tải lại trang nhé.</p><button onclick="location.reload()">Thử lại</button></main>`;console.error(error);}
